(()=>{const root=document.getElementById('I06-lab');if(!root)return;const zh=document.documentElement.lang.startsWith('zh'),tr=(a,b)=>zh?a:b,q=id=>root.querySelector('#I06-'+id);let s={shift_percent:0,size_nm:30,instrument_deg:.12};const ls=[];function render(){s.d_nm=.25*(1+s.shift_percent/100);const theta=Math.asin(.15406/(2*s.d_nm));s.center_deg=theta*360/Math.PI;s.intrinsic_deg=.9*.15406/(s.size_nm*Math.cos(theta))*180/Math.PI;s.observed_deg=Math.hypot(s.intrinsic_deg,s.instrument_deg);s.naive_nm=.9*.15406/(s.observed_deg*Math.PI/180*Math.cos(theta));s.corrected_nm=.9*.15406/(Math.sqrt(s.observed_deg*s.observed_deg-s.instrument_deg*s.instrument_deg)*Math.PI/180*Math.cos(theta));q('shift').value=s.shift_percent;q('size').value=s.size_nm;q('instrument').value=s.instrument_deg;const x=Array.from({length:601},(_,i)=>33+i*.01),curves=[s.intrinsic_deg,s.observed_deg].map(w=>x.map(a=>Math.exp(-4*Math.log(2)*((a-s.center_deg)/w)**2)/w)),ymax=Math.max(...curves.flat())*1.1;let v='<rect width="800" height="360" fill="#faf9f5"/><path d="M60 30V300H775" fill="none" stroke="#788b90"/>';for(let a=33;a<=39;a++)v+=`<text x="${60+(a-33)/6*715}" y="323" text-anchor="middle">${a}</text>`;curves.forEach((c,k)=>{const d=c.map((y,i)=>(i?'L':'M')+(60+i/600*715).toFixed(2)+' '+(300-y/ymax*260).toFixed(2)).join(' ');v+=`<path d="${d}" fill="none" stroke="${k?'#3474a8':'#168477'}" stroke-width="${k?3:2}"/>`});v+=`<text x="420" y="350" text-anchor="middle">2θ / °</text><text x="70" y="20">${tr('等面积相对强度','Equal-area relative intensity')}</text>`;q('plot').innerHTML=v;q('result').textContent=tr('峰位','Peak')+` ${s.center_deg.toFixed(3)}° · `+tr('观测半高全宽','Observed FWHM')+` ${s.observed_deg.toFixed(4)}° · `+tr('未修正尺寸','Uncorrected size')+` ${s.naive_nm.toFixed(2)} nm · `+tr('高斯修正尺寸','Gaussian-corrected size')+` ${s.corrected_nm.toFixed(2)} nm`;}function set(p){for(const [k,lo,hi] of [['shift_percent',-2,2],['size_nm',10,100],['instrument_deg',.03,.4]])if(p[k]!==undefined)s[k]=Math.min(hi,Math.max(lo,+p[k]));render();return {...s}}function on(id,e,f){q(id).addEventListener(e,f);ls.push([q(id),e,f])}on('shift','input',e=>set({shift_percent:+e.target.value}));on('size','input',e=>set({size_nm:+e.target.value}));on('instrument','input',e=>set({instrument_deg:+e.target.value}));const reset=()=>set({shift_percent:0,size_nm:30,instrument_deg:.12});on('reset','click',reset);window.CourseLab={set,state:()=>({...s}),reset,destroy:()=>ls.forEach(([n,e,f])=>n.removeEventListener(e,f))};render();})();
